class Solution:
    def adjacentColors(self, n: int, queries: List[List[int]]) -> List[int]:
        ans = []
        for i in range(n):
            ans.append(0)
        for i in range(n):
            for j in range(i+1, n):
                if queries[i][0] == queries[j][0] and queries[i][1] == queries[j][1]:
                    ans[i] += 1
        return ans

class Solution:
    def powerOfGroups(self, nums: List[int]) -> int:
        """
        :type nums: List[int]
        :rtype: int
        """
        power = 0
        for i in range(len(nums)):
            power += (nums[i] ** 2) * min(nums[i], nums[i+1])
        return power % 10**9 + 7

