class Solution:
    def minSwaps(self, nums: List[int]) -> int:
        if not nums:
            return 0

        def swap(i, j):
            if i == j:
                return

            nums[i], nums[j] = nums[j], nums[i]

            swap(i + 1, j)
            swap(i, j + 1)
            swap(i + 1, j + 1)

        swap(0, 1)
        swap(1, 2)
        swap(2, 3)

        return min(swap(i, j) for i in range(len(nums) - 1) for j in range(i + 1, len(nums)))

