class Solution:
    def maxPairs(self, words: List[str]) -> int:
        """
        :type words: List[str]
        :rtype: int
        """
        if not words:
            return 0

        def helper(words, i, j):
            if i == j:
                return 1

            if words[i] == words[j]:
                return helper(words, i+1, j) + helper(words, i, j+1)

            return helper(words, i+1, j)

        return max(helper(words, 0, len(words)-1))

class Solution:
    def numSubarrays(self, nums: List[int]) -> int:
        """
        :type nums: List[int]
        :rtype: int
        """
        if not nums:
            return 0
        nums.sort()
        res = 0
        for i in range(len(nums)):
            if nums[i] == 1:
                res += 1
        return res % 10**9 + 7

class Solution:
    def longestSubarray(self, nums1: List[int], nums2: List[int]) -> int:
        if len(nums1) == 0 or len(nums2) == 0:
            return 0

        nums3 = [nums1[0], nums2[0]]

        for i in range(1, len(nums1)):
            if nums1[i] > nums2[i]:
                nums3.append(nums1[i])
            else:
                nums3.append(nums2[i])

        return max(len(nums3), len(nums1) + len(nums2))

