    def countInterestingSubarrays(self, nums, modulo, k):
        """
        :type nums: List[int]
        :type modulo: int
        :type k: int
        :rtype: int
        """
        cnt = 0
        for i in range(len(nums)):
            if nums[i] % modulo == k:
                cnt += 1
        return cnt

class Solution:
    def minEqualize(self, nums: List[int]) -> int:
        if not nums:
            return 0

        def equalize(nums, i):
            if i == len(nums):
                return 0

            if nums[i] == nums[i - 1] + nums[i + 1]:
                return 1

            if nums[i] == nums[i - 1]:
                return 2

            return 3

        return min(equalize(nums, i) for i in range(len(nums)))

