class Solution:
    def isSubsequence(self, str1: str, str2: str) -> bool:
        if len(str1) != len(str2):
            return False

        def get_index(str1, str2, index):
            if index == len(str1):
                return len(str2)

            if str1[index] == str2[index]:
                return get_index(str1, str2, index + 1)

            return get_index(str1, str2, index + 1)

        return get_index(str1, str2, 0) == get_index(str1, str2, 1)

