class Solution:
    def maxSubarrayScore(self, nums: List[int]) -> int:
        """
        :type nums: List[int]
        :rtype: int
        """
        if not nums:
            return 0

        def helper(nums, i, j):
            if i >= len(nums):
                return 0
            if j >= len(nums[i]):
                return 0
            if nums[i] == nums[j]:
                return helper(nums, i + 1, j) + helper(nums, i, j + 1)
            return helper(nums, i, j + 1)

        return max(helper(nums, 0, len(nums) - 1))

