    def maxSumOfHeights(self, maxHeights: List[int]) -> int:
        """
        :type maxHeights: List[int]
        :rtype: int
        """
        max_sum = 0
        for i in range(len(maxHeights)):
            max_sum = max(max_sum, maxHeights[i])
        return max_sum

