class Solution:
    def findWords(self, words: List[str], x: str) -> List[int]:
        """
        :type words: List[str]
        :type x: str
        :rtype: List[int]
        """
        if not words:
            return []
        if not x:
            return []
        if x == '':
            return []
        if x in words:
            return [i for i, w in enumerate(words) if x in w]
        return []

class Solution:
    def maxFreq(self, nums: List[int], k: int) -> int:
        freq = {}
        for i in range(len(nums)):
            freq[nums[i]] = freq.get(nums[i], 0) + 1
        return max(freq.values())

class Solution:
    def countBeautifulSubstrings(self, s, k):
        vowels = 0
        consonants = 0
        for i in range(len(s)):
            if s[i] in 'aeiou':
                vowels += 1
            else:
                consonants += 1
        return (vowels * consonants) % k

class Solution:
    def maxPerimeter(self, nums: List[int]) -> int:
        if not nums:
            return -1
        max_perimeter = 0
        for i in range(len(nums)):
            if i == 0:
                max_perimeter = max(nums[i], max_perimeter)
            else:
                max_perimeter = max(max_perimeter, nums[i] + nums[i-1] + nums[i+1])
        return max_perimeter
