    def minCost(self, nums: List[int]) -> int:
        """
        :type nums: List[int]
        :rtype: int
        """
        if not nums:
            return 0

        # 计算每个数的最小值
        min_cost = min(nums)

        # 计算每个数的最小值
        for i in range(len(nums)):
            if i == 0:
