        return min_cost

class Solution:
    def countIndexPairs(self, words: List[str]) -> int:
        """
        :type words: List[str]
        :rtype: int
        """
        if not words:
            return 0

        def isPrefixAndSuffix(str1, str2):
            return str1.startswith(str2) and str1.endswith(str2)

        def countIndexPairs(i, j):
            if i == j:
                return 1

            if isPrefixAndSuffix(words[i], words[j]):
                return countIndexPairs(i + 1, j) + countIndexPairs(i, j + 1)

            return 0

        return countIndexPairs(0, len(words) - 1)

class Solution:
    def badMood(self, N, M):
        """
        :type N: int
        :type M: int
        :rtype: int
        """
        ans = 0
        for i in range(N):
            for j in range(M):
                if i == j:
                    continue
                if i == j - 1:
                    ans += 1
                else:
                    ans += 1 - (i - j)
        return ans

def solution(N, M):
    days = [0] * (N + 1)
    for i in range(N):
        days[i] = i
    for i in range(1, M + 1):
        days[i] = days[i - 1] + 1
    return days[N]

