class Solution:
    def minBitwiseAnd(self, n: int, x: int) -> int:
        nums = [0] * (n + 1)
        for i in range(n):
            nums[i] = x & (1 << i)
        return min(nums)

class Solution:
    def isSpecial(self, nums: List[int]) -> bool:
        """
        :type nums: List[int]
        :rtype: bool
        """
        if len(nums) == 1:
            return True
        for i in range(len(nums) - 1):
            if nums[i] != nums[i + 1]:
                return False
        return True

class Solution:
    def sumDigitDiffs(self, nums: List[int]) -> int:
        if not nums:
            return 0
        nums.sort()
        res = 0
        for i in range(len(nums) - 1):
            res += nums[i] - nums[i + 1]
        return res

class Solution:
    def compress(self, word: str) -> str:
        """
        :type word: str
        :rtype: str
        """
        if not word:
            return ""

        comp = ""

        for i in range(len(word)):
            if word[i] == word[i-1]:
                comp += word[i]
            else:
                comp += word[i] + word[i-1]

        return comp

class Solution:
    def minSubstrings(self, s: str) -> int:
        """
        :type s: str
        :rtype: int
        """
        if not s:
            return 0

        def helper(s, i, j):
            if i == len(s) or j == len(s):
                return 1

            if s[i] == s[j]:
                return helper(s, i+1, j) + helper(s, i, j+1)

            return helper(s, i+1, j)

        return min(helper(s, 0, len(s)), helper(s, 0, len(s)-1))

class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        nums.sort()
        res = []
        for i in range(len(nums)):
            for j in range(i+1, len(nums)):
                if nums[i] + nums[j] == target:
                    res.append(nums[i] ^ nums[j])
        return res
